<?php
declare(strict_types=1);
namespace DigiForge\POD;

/** Exact simulated checks against reviewed dimensions and actual decoded pixels. */
final class ArtworkPixelQa {
 public static function verify(array $areas,array $images):array {
  if(!array_is_list($areas)||$areas===[]||count($areas)>32||count($images)>32)throw new \InvalidArgumentException('Bounded complete panel geometry required.');
  $panels=[];$policies=[];$total=0;$pairs=[];
  foreach($areas as $area){$position=$area['position']??null;if(!is_string($position)||!preg_match('/^[a-z][a-z0-9_-]{0,63}$/D',$position)||isset($panels[$position]))throw new \InvalidArgumentException('Exact unique panel identities required.');$policies[$position]=ArtworkGeometryQa::policy($area);$panels[$position]=['bleed_pixels'=>'MISSING_BLEED_GEOMETRY'];
   if(array_key_exists('panel_edge_matches',$area)){$matches=$area['panel_edge_matches'];if(!is_array($matches)||!array_is_list($matches)||$matches===[]||count($matches)>8)throw new \InvalidArgumentException('Explicit bounded edge matches required.');foreach($matches as $match){if(!is_array($match)||count($match)!==4||array_diff(array_keys($match),['edge','other_panel','other_edge','reverse'])!==[]||!in_array($match['edge']??null,['left','right','top','bottom'],true)||!in_array($match['other_edge']??null,['left','right','top','bottom'],true)||!is_string($match['other_panel']??null)||!is_bool($match['reverse']??null))throw new \InvalidArgumentException('Exact reviewed edge correspondence required.');$pairs[]=[$position,$match];}}
  }
  foreach($images as $position=>$image){if(!isset($panels[$position])||!is_array($image)||!is_int($image['width_px']??null)||!is_int($image['height_px']??null)||!is_string($image['rgba']??null))throw new \InvalidArgumentException('Decoded complete panel pixels required.');RasterArtworkCodec::geometry($image['width_px'],$image['height_px']);if(strlen($image['rgba'])!==$image['width_px']*$image['height_px']*4)throw new \InvalidArgumentException('Incomplete decoded pixel stream.');$total+=$image['width_px']*$image['height_px'];if($total>RasterArtworkCodec::MAX_PIXELS*8)throw new \InvalidArgumentException('Aggregate panel QA exceeds work bound.');}
  foreach($areas as $area){$position=$area['position'];$policy=$policies[$position];if(!isset($policy['bleed']))continue;$image=self::image($area,$images);$trim=$policy['bleed']['trim_box'];for($y=0;$y<$image['height_px'];$y++)for($x=0;$x<$image['width_px'];$x++)if(($x<$trim['x']||$y<$trim['y']||$x>=$trim['x']+$trim['width']||$y>=$trim['y']+$trim['height'])&&ord($image['rgba'][($y*$image['width_px']+$x)*4+3])!==255)throw new \InvalidArgumentException('Actual bleed band has uncovered or translucent pixels.');$panels[$position]['bleed_pixels']='VERIFIED_LOCAL_BLEED_PIXELS';}
  $byPosition=array_column($areas,null,'position');$seen=[];foreach($pairs as [$position,$match]){$other=$match['other_panel'];if(!isset($byPosition[$other])||($other===$position&&$match['edge']===$match['other_edge']))throw new \InvalidArgumentException('Reviewed edge target must exist and cannot match itself.');$identity=$position.':'.$match['edge'];if(isset($seen[$identity]))throw new \InvalidArgumentException('Ambiguous duplicate edge correspondence.');$seen[$identity]=true;$left=self::edge(self::image($byPosition[$position],$images),$match['edge']);$right=self::edge(self::image($byPosition[$other],$images),$match['other_edge']);if($match['reverse'])$right=implode('',array_reverse(str_split($right,4)));if(!hash_equals($left,$right))throw new \InvalidArgumentException('Actual panel edge pixels do not match reviewed correspondence.');}
  return ['panels'=>$panels,'panel_continuity'=>$pairs===[]?'MISSING_PANEL_CONTINUITY_CONTRACT':'VERIFIED_LOCAL_EDGE_CONTINUITY','supplier_certified'=>false,'external_execution_authorized'=>false];
 }
 private static function image(array $area,array $images):array {$image=$images[$area['position']]??null;if(!is_array($image)||$image['width_px']!==$area['width_px']||$image['height_px']!==$area['height_px'])throw new \InvalidArgumentException('Exact decoded template panel required.');return $image;}
 private static function edge(array $image,string $edge):string {$width=$image['width_px'];$height=$image['height_px'];if($edge==='top'||$edge==='bottom')return substr($image['rgba'],($edge==='top'?0:$height-1)*$width*4,$width*4);$out='';for($y=0;$y<$height;$y++)$out.=substr($image['rgba'],($y*$width+($edge==='left'?0:$width-1))*4,4);return $out;}
}
